// ---------- graders: GRADER[type](challenge, answer) -> {grade:'strong'|'weak'|'fail', notes} ----------
// Authored rubrics only. No API calls anywhere.
const GRADER={
  fix(L,choice){return {grade:choice===L.f[3]?'strong':'weak',notes:L.f[4]};},
  write(L,a){const c=L.c;let s=0,bad=0;for(const p of a.picks){const i=c.indexOf(p);if(i>=1&&i<=3)s+=2;else if(i>3){s-=1;bad++;}}if((a.text||'').trim().length>=3)s+=1;
    return {score:s,grade:s>=5?'strong':s>=2?'weak':'fail',notes:s>=5?'Strong prompt: specific, with nothing vague.':bad?'A vague block is dragging it down. Swap it out.':'Nearly. Add another strong block, or a line of your own.'};},
  quest(L,vals){return {grade:vals.length>0&&vals.every(v=>v.trim().length>=2)?'strong':'weak',notes:''};},
  order(ch,ans){let ok=0;for(let i=0;i<ch.parts.length;i++)if(ans[i]===i)ok++;return {grade:ok===ch.parts.length?'strong':ok>=ch.parts.length-2?'weak':'fail',notes:ch.why};}
};
